class Solution {
public:
    int openLock(vector<string>& deadends, string target) {
        unordered_set<string> dead(deadends.begin(), deadends.end());
        if (dead.count("0000")) return -1;
        if (target == "0000") return 0;

        queue<pair<string, int>> q;
        unordered_set<string> visited = {"0000"};
        q.push({"0000", 0});

        while (!q.empty()) {
            auto [state, steps] = q.front();
            q.pop();
            if (state == target) return steps;
            for (int i = 0; i < 4; i++) {
                char orig = state[i];
                for (int diff : {-1, 1}) {
                    state[i] = (orig - '0' + diff + 10) % 10 + '0';
                    if (!dead.count(state) && !visited.count(state)) {
                        visited.insert(state);
                        q.push({state, steps + 1});
                    }
                }
                state[i] = orig;
            }
        }
        return -1;
    }
};

class Solution {
    public int openLock(String[] deadends, String target) {
        Set<String> dead = new HashSet<>(Arrays.asList(deadends));
        if (dead.contains("0000")) return -1;
        if (target.equals("0000")) return 0;

        Queue<String> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        queue.offer("0000");
        visited.add("0000");
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int k = 0; k < size; k++) {
                String state = queue.poll();
                if (state.equals(target)) return steps;
                char[] chars = state.toCharArray();
                for (int i = 0; i < 4; i++) {
                    char orig = chars[i];
                    for (int diff : new int[]{-1, 1}) {
                        chars[i] = (char) ((orig - '0' + diff + 10) % 10 + '0');
                        String nxt = new String(chars);
                        if (!dead.contains(nxt) && !visited.contains(nxt)) {
                            visited.add(nxt);
                            queue.offer(nxt);
                        }
                    }
                    chars[i] = orig;
                }
            }
            steps++;
        }
        return -1;
    }
}

var openLock = function(deadends, target) {
    const dead = new Set(deadends);
    if (dead.has("0000")) return -1;
    if (target === "0000") return 0;

    const queue = [["0000", 0]];
    const visited = new Set(["0000"]);

    while (queue.length > 0) {
        const [state, steps] = queue.shift();
        if (state === target) return steps;
        for (let i = 0; i < 4; i++) {
            const digit = Number(state[i]);
            for (const diff of [-1, 1]) {
                const nextDigit = (digit + diff + 10) % 10;
                const nextState = state.slice(0, i) + nextDigit + state.slice(i + 1);
                if (!dead.has(nextState) && !visited.has(nextState)) {
                    visited.add(nextState);
                    queue.push([nextState, steps + 1]);
                }
            }
        }
    }
    return -1;
};
